import{_ as e,C as n,c as i,o as t,j as r,G as a,b as s,a0 as l,a as h,w as u,a1 as d}from"./chunks/framework.DKRgXLPU.js";const o=JSON.parse('{"title":"Ernährung für präzise Leistungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/education/nutrition/index.md","filePath":"de/education/nutrition/index.md"}');const g=e({name:"de/education/nutrition/index.md"},[["render",function(e,o,g,c,m,p){const b=n("AdBanner"),f=n("Mermaid"),k=n("AdInArticle");return t(),i("div",null,[o[2]||(o[2]=r("h1",{id:"ernahrung-fur-prazise-leistungen",tabindex:"-1"},[h("Ernährung für präzise Leistungen "),r("a",{class:"header-anchor",href:"#ernahrung-fur-prazise-leistungen","aria-label":'Permalink to "Ernährung für präzise Leistungen"'},"​")],-1)),a(b),o[3]||(o[3]=r("p",null,[h("Pétanque ist ein Präzisionssport, kein Ausdauersport. Ihre Ernährungsbedürfnisse unterscheiden sich von denen eines Marathonläufers oder Fußballspielers. Am wichtigsten ist eine "),r("strong",null,"stabile Energieversorgung des Gehirns"),h(" – damit Sie den ganzen Wettkampftag über konzentriert und ruhig bleiben.")],-1)),o[4]||(o[4]=r("div",{class:"tip custom-block"},[r("p",{class:"custom-block-title"},"Die große Idee"),r("p",null,[r("strong",null,"Ihr Gehirn ist Ihr wichtigstes Werkzeug beim Boule. Versorgen Sie es mit stabiler Energie, nicht mit Achterbahnfahrten."),h(" Achten Sie auf Eiweiß, gesunde Fette und ausreichend Flüssigkeitszufuhr. Vermeiden Sie Blutzuckerspitzen.")])],-1)),(t(),s(d,null,{default:u(()=>[a(f,{id:"mermaid-13",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BZucker%2FEinfache%20Kohlenhydrate%5D%20--%3E%20B%5BBlutzuckeranstieg%5D%0A%20%20%20%20B%20--%3E%20C%5BInsulinfreisetzung%5D%0A%20%20%20%20C%20--%3E%20D%5BBlutzuckerabfall%5D%0A%20%20%20%20D%20--%3E%20E%5BAdrenalinreaktion%5D%0A%20%20%20%20E%20--%3E%20F%5BZittern%20und%20Angstzust%C3%A4nde%5D%0A%0A%20%20%20%20G%5BProtein%20und%20gesunde%20Fette%5D%20--%3E%20H%5BStabiler%20Blutzucker%5D%0A%20%20%20%20H%20--%3E%20I%5BKonstante%20Energie%5D%0A%20%20%20%20I%20--%3E%20J%5BScharfer%20Fokus%5D%0A%20%20%20%20J%20--%3E%20K%5BRuhige%20H%C3%A4nde%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffebee%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20G%20fill%3A%23e8f5e9%0A%20%20%20%20style%20K%20fill%3A%23e8f5e9%0A"})]),fallback:u(()=>[...o[0]||(o[0]=[h(" Loading... ",-1)])]),_:1})),o[5]||(o[5]=l('<h2 id="die-herausforderung-fur-prazisionsathleten" tabindex="-1">Die Herausforderung für Präzisionsathleten <a class="header-anchor" href="#die-herausforderung-fur-prazisionsathleten" aria-label="Permalink to &quot;Die Herausforderung für Präzisionsathleten&quot;">​</a></h2><p>Im Gegensatz zu Hochleistungssportarten benötigt Pétanque keine großen Glykogenspeicher oder eine schnelle Energiezufuhr. Was es erfordert, ist Folgendes:</p><ul><li><strong>Stabiler Blutzucker</strong> – keine Spitzen oder Abfälle</li><li><strong>Konstante geistige Klarheit</strong> – Konzentration, die den ganzen Tag anhält.</li><li><strong>Ruhige Hände</strong> – kein Zittern oder Beben</li><li><strong>Beruhigte Nerven</strong> – geringe Angst- und Stressreaktion</li></ul><p>Ihre Ernährungsstrategie sollte diese Faktoren optimieren, nicht die reine Energieausbeute.</p><h2 id="das-problem-mit-zucker-und-einfachen-kohlenhydraten" tabindex="-1">Das Problem mit Zucker und einfachen Kohlenhydraten <a class="header-anchor" href="#das-problem-mit-zucker-und-einfachen-kohlenhydraten" aria-label="Permalink to &quot;Das Problem mit Zucker und einfachen Kohlenhydraten&quot;">​</a></h2><p>Viele Sportler greifen standardmäßig auf kohlenhydratreiche Ernährung zurück. Für Boule-Spieler kann dies die Leistung sogar beeinträchtigen.</p><h3 id="die-blutzucker-achterbahn" tabindex="-1">Die Blutzucker-Achterbahn <a class="header-anchor" href="#die-blutzucker-achterbahn" aria-label="Permalink to &quot;Die Blutzucker-Achterbahn&quot;">​</a></h3><p>Wenn Sie Zucker oder einfache Kohlenhydrate essen:</p><ol><li>Der Blutzuckerspiegel steigt rapide an</li><li>Insulin wird freigesetzt, um den Spiegel zu senken.</li><li>Blutzuckerabfall (Hypoglykämie)</li><li>Ihr Körper schüttet Adrenalin aus, um dies auszugleichen.</li><li>Sie leiden unter Zittern, Angstzuständen und Konzentrationsschwierigkeiten.</li></ol><p>Das ist genau das Gegenteil von dem, was Sie für Präzision benötigen.</p><h3 id="symptome-einer-blutzuckerinstabilitat" tabindex="-1">Symptome einer Blutzuckerinstabilität <a class="header-anchor" href="#symptome-einer-blutzuckerinstabilitat" aria-label="Permalink to &quot;Symptome einer Blutzuckerinstabilität&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Auswirkungen auf die Leistung</th></tr></thead><tbody><tr><td>Zitternde Hände</td><td>Uneinheitliche Veröffentlichung</td></tr><tr><td>Konzentrationsschwierigkeiten</td><td>Schlechte Entscheidungsfindung</td></tr><tr><td>Reizbarkeit</td><td>Teamkonflikte, mangelnde Gelassenheit</td></tr><tr><td>Müdigkeit nach dem Essen</td><td>Nachmittagstief</td></tr><tr><td>Angst</td><td>Druckempfindlichkeit</td></tr><tr><td>Gehirnnebel</td><td>Langsames taktisches Denken</td></tr></tbody></table><h2 id="ein-besserer-ansatz-stabile-energie" tabindex="-1">Ein besserer Ansatz: Stabile Energie <a class="header-anchor" href="#ein-besserer-ansatz-stabile-energie" aria-label="Permalink to &quot;Ein besserer Ansatz: Stabile Energie&quot;">​</a></h2><p>Das Ziel ist es, Ihrem Gehirn gleichmäßig Energie zuzuführen, ohne die üblichen Schwankungen.</p><h3 id="grundprinzipien" tabindex="-1">Grundprinzipien <a class="header-anchor" href="#grundprinzipien" aria-label="Permalink to &quot;Grundprinzipien&quot;">​</a></h3><ol><li><strong>Eiweiß und gesunde Fette sollten Vorrang haben</strong> – sie liefern langsame, gleichmäßige Energie.</li><li><strong>Wählen Sie komplexe Kohlenhydrate statt einfacher Kohlenhydrate</strong> – Wenn Sie Kohlenhydrate essen, wählen Sie solche, die langsam verdaut werden.</li><li><strong>Vermeiden Sie Blutzuckerspitzen</strong> – insbesondere vor und während des Wettkampfs</li><li><strong>Achten Sie auf ausreichende Flüssigkeitszufuhr</strong> – Flüssigkeitsmangel beeinträchtigt die Konzentration erheblich.</li><li><strong>Essen Sie regelmäßig</strong> – Lassen Sie es nicht zu, dass Sie zu hungrig werden.</li></ol><h3 id="lebensmittel-die-helfen" tabindex="-1">Lebensmittel, die helfen <a class="header-anchor" href="#lebensmittel-die-helfen" aria-label="Permalink to &quot;Lebensmittel, die helfen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Lebensmittelart</th><th>Beispiele</th><th>Warum es funktioniert</th></tr></thead><tbody><tr><td>Protein</td><td>Eier, Nüsse, Käse, Fleisch</td><td>Langsame Verdauung, stabile Energie</td></tr><tr><td>Gesunde Fette</td><td>Avocado, Olivenöl, Nüsse</td><td>Langlebiger Kraftstoff</td></tr><tr><td>Komplexe Kohlenhydrate</td><td>Gemüse, Hülsenfrüchte</td><td>Ballaststoffe verlangsamen die Absorption</td></tr><tr><td>zuckerarme Früchte</td><td>Beeren, Äpfel</td><td>Nährstoffe ohne Spitzenwerte</td></tr></tbody></table><h3 id="lebensmittel-die-man-einschranken-sollte" tabindex="-1">Lebensmittel, die man einschränken sollte <a class="header-anchor" href="#lebensmittel-die-man-einschranken-sollte" aria-label="Permalink to &quot;Lebensmittel, die man einschränken sollte&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Lebensmittelart</th><th>Beispiele</th><th>Warum das problematisch ist</th></tr></thead><tbody><tr><td>Zucker</td><td>Süßigkeiten, Limonade, Gebäck</td><td>Rasanter Anstieg und Absturz</td></tr><tr><td>Weißbrot/Nudeln</td><td>Sandwiches, Pastagerichte</td><td>Schnelle Umwandlung in Zucker</td></tr><tr><td>Fruchtsaft</td><td>Orangensaft, Smoothies</td><td>Konzentrierter Zucker</td></tr><tr><td>Energy-Drinks</td><td>Die meisten Handelsmarken</td><td>Zucker- und Koffein-Crash</td></tr></tbody></table><h2 id="ernahrung-am-wettkampftag" tabindex="-1">Ernährung am Wettkampftag <a class="header-anchor" href="#ernahrung-am-wettkampftag" aria-label="Permalink to &quot;Ernährung am Wettkampftag&quot;">​</a></h2><h3 id="vor-dem-wettbewerb" tabindex="-1">Vor dem Wettbewerb <a class="header-anchor" href="#vor-dem-wettbewerb" aria-label="Permalink to &quot;Vor dem Wettbewerb&quot;">​</a></h3><p><strong>2-3 Stunden vorher:</strong></p><ul><li>Ausgewogene Mahlzeit mit Eiweiß, Fett und Gemüse</li><li>Vermeiden Sie kohlenhydratreiche Lebensmittel, die Schläfrigkeit verursachen könnten.</li><li>Beispiel: Eier mit Gemüse oder Salat mit Hähnchen</li></ul><p><strong>1 Stunde vorher:</strong></p><ul><li>Bei Bedarf einen kleinen Snack.</li><li>Nüsse, Käse oder eine kleine Portion Eiweiß</li><li>Vermeiden Sie alles Zuckerische</li></ul><h3 id="wahrend-des-wettbewerbs" tabindex="-1">Während des Wettbewerbs <a class="header-anchor" href="#wahrend-des-wettbewerbs" aria-label="Permalink to &quot;Während des Wettbewerbs&quot;">​</a></h3><p><strong>Zwischen den Spielen:</strong></p><ul><li>Wasser (am wichtigsten)</li><li>Kleine proteinreiche Snacks (Nüsse, Käse, Fleisch)</li><li>Vermeiden Sie zuckerhaltige Snacks und Getränke.</li></ul><p><strong>Anzeichen dafür, dass Sie etwas essen müssen:</strong></p><ul><li>Konzentrationsschwierigkeiten</li><li>Reizbarkeit</li><li>Ich fühle mich zittrig</li><li>Kopfschmerzen</li></ul><h3 id="nach-dem-wettbewerb" tabindex="-1">Nach dem Wettbewerb <a class="header-anchor" href="#nach-dem-wettbewerb" aria-label="Permalink to &quot;Nach dem Wettbewerb&quot;">​</a></h3><ul><li>Stärken Sie Ihre Energiespeicher mit einer ausgewogenen Mahlzeit.</li><li>Vollständig rehydrieren</li><li>Belohnen Sie sich nicht mit Zucker – das beeinträchtigt Ihre Genesung.</li></ul><h2 id="flussigkeitszufuhr" tabindex="-1">Flüssigkeitszufuhr <a class="header-anchor" href="#flussigkeitszufuhr" aria-label="Permalink to &quot;Flüssigkeitszufuhr&quot;">​</a></h2><p>Dehydrierung beeinträchtigt die kognitive Funktion, bevor man Durst verspürt.</p><h3 id="richtlinien" tabindex="-1">Richtlinien <a class="header-anchor" href="#richtlinien" aria-label="Permalink to &quot;Richtlinien&quot;">​</a></h3><ul><li><strong>Gut hydriert in den Wettkampf starten</strong> - Trinken Sie den ganzen Tag über vor dem Wettkampf Wasser.</li><li><strong>Während des Spielens</strong> – Trinken Sie regelmäßig kleine Schlucke Wasser, warten Sie nicht, bis Sie durstig sind.</li><li><strong>Übermäßigen Koffeinkonsum vermeiden</strong> – Koffein wirkt harntreibend.</li><li><strong>Achten Sie auf folgende Anzeichen:</strong> – Kopfschmerzen, dunkler Urin, Müdigkeit</li></ul><h3 id="wie-viel" tabindex="-1">Wie viel? <a class="header-anchor" href="#wie-viel" aria-label="Permalink to &quot;Wie viel?&quot;">​</a></h3><p>Als allgemeine Richtlinie gilt: Der Urin sollte hellgelb sein. Ist er dunkel, benötigen Sie mehr Wasser.</p><h2 id="die-kohlenhydratarme-option" tabindex="-1">Die kohlenhydratarme Option <a class="header-anchor" href="#die-kohlenhydratarme-option" aria-label="Permalink to &quot;Die kohlenhydratarme Option&quot;">​</a></h2><p>Manche Präzisionssportler setzen auf kohlenhydratarme oder ketogene Diäten. Die Theorie:</p><p><strong>Mögliche Vorteile:</strong></p><ul><li>Sehr stabiler Blutzucker (keine Blutzuckerspitzen möglich)</li><li>Konstante geistige Klarheit</li><li>Verringerte Angstzustände und Zittern</li><li>Kein Energietief am Nachmittag</li></ul><p><strong>Zu berücksichtigen:</strong></p><ul><li>Erfordert eine Eingewöhnungszeit (1-2 Wochen).</li><li>Nicht für jeden geeignet</li><li>Erfordert Planung und Engagement</li><li>Konsultieren Sie zuerst einen Arzt oder eine andere medizinische Fachkraft.</li></ul>',45)),a(k),o[6]||(o[6]=l('<p>Dies ist eine fortgeschrittene Strategie – nicht für jeden notwendig, aber eine Überlegung wert, wenn die Blutzuckerstabilität für Sie ein wichtiges Thema ist.</p><h2 id="essen-als-training-trainiere-deinen-korper" tabindex="-1">Essen als Training: Trainiere deinen Körper <a class="header-anchor" href="#essen-als-training-trainiere-deinen-korper" aria-label="Permalink to &quot;Essen als Training: Trainiere deinen Körper&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Kritisches Konzept</p><p><strong>Essen ist nicht nur Treibstoff – es ist etwas, mit dem man übt.</strong> Genau wie du deinen Wurf übst, musst du auch deine Ernährung üben, damit sich dein Körper an die Nahrungsaufnahme am Wettkampftag gewöhnt.</p></div><h3 id="warum-ernahrungsgewohnheiten-wichtig-sind" tabindex="-1">Warum Ernährungsgewohnheiten wichtig sind <a class="header-anchor" href="#warum-ernahrungsgewohnheiten-wichtig-sind" aria-label="Permalink to &quot;Warum Ernährungsgewohnheiten wichtig sind&quot;">​</a></h3><p>Dein Verdauungssystem ist trainierbar. Was du regelmäßig isst, wird zu dem, was dein Körper erwartet und am besten verarbeitet. Wenn du an Wettkampftagen nur Eiweiß und Gemüse zu dir nimmst, gewöhnt sich dein Körper nicht daran.</p><p><strong>Das Problem:</strong></p><ul><li>Der Verzehr ungewohnter Speisen am Wettkampftag kann Verdauungsbeschwerden verursachen.</li><li>Ihr Körper braucht Zeit, sich an neue Ernährungsmuster anzupassen.</li><li>Stress + ungewohntes Essen = mögliche Magenprobleme</li><li>Leistungsangst ist schon schlimm genug, ohne dass noch Verdauungsangst hinzukommt.</li></ul><p><strong>Die Lösung:</strong></p><ul><li>Setze deine Wettkampfernährung während des Trainings um.</li><li>Integriere die Speisen, die du am Wettkampftag zu dir nimmst, in deine normale Ernährung.</li><li>Trainieren Sie Ihren Körper, sich an Nahrungsmittel mit gleichmäßiger Energiezufuhr zu gewöhnen.</li></ul><h3 id="der-anpassungsprozess" tabindex="-1">Der Anpassungsprozess <a class="header-anchor" href="#der-anpassungsprozess" aria-label="Permalink to &quot;Der Anpassungsprozess&quot;">​</a></h3>',10)),(t(),s(d,null,{default:u(()=>[a(f,{id:"mermaid-590",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BAktuelle%20Ern%C3%A4hrung%5D%20--%3E%20B%5BAllm%C3%A4hliche%20Ver%C3%A4nderungen%5D%0A%20%20%20%20B%20--%3E%20C%5BK%C3%B6rperanpassung%20%3Cbr%2F%3E%202-4%20Wochen%5D%0A%20%20%20%20C%20--%3E%20D%5BNeue%20Normalit%C3%A4t%5D%0A%20%20%20%20D%20--%3E%20E%5BWettbewerbsbereit%5D%0A%0A%20%20%20%20F%5BPl%C3%B6tzliche%20Ver%C3%A4nderung%20%3Cbr%2F%3E%20Wettkampftag%5D%20--%3E%20G%5BVerdauungsbeschwerden%5D%0A%20%20%20%20G%20--%3E%20H%5BSchlechte%20Leistung%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff3e0%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20H%20fill%3A%23ffebee%0A"})]),fallback:u(()=>[...o[1]||(o[1]=[h(" Loading... ",-1)])]),_:1})),o[7]||(o[7]=l('<p>Wenn Sie Ihre Ernährung umstellen:</p><ol><li><strong>Woche 1-2:</strong> Ihr Körper gewöhnt sich an neue Nahrungsmittel, Sie fühlen sich möglicherweise anders.</li><li><strong>Woche 3-4:</strong> Die Anpassung erfolgt, neue Lebensmittel werden als normal empfunden.</li><li><strong>Woche 5+:</strong> Ihr Körper hat sich an diese Lebensmittel gewöhnt und verträgt sie optimal.</li></ol><p><strong>Deshalb reicht es nicht, sich am Wettkampftag einfach nur &quot;gesund zu ernähren&quot; und optimale Ergebnisse zu erwarten.</strong></p><h3 id="wie-sie-ihre-ernahrung-in-die-praxis-umsetzen" tabindex="-1">Wie Sie Ihre Ernährung in die Praxis umsetzen <a class="header-anchor" href="#wie-sie-ihre-ernahrung-in-die-praxis-umsetzen" aria-label="Permalink to &quot;Wie Sie Ihre Ernährung in die Praxis umsetzen&quot;">​</a></h3><h4 id="_1-beginnen-sie-wahrend-des-trainings" tabindex="-1">1. Beginnen Sie während des Trainings <a class="header-anchor" href="#_1-beginnen-sie-wahrend-des-trainings" aria-label="Permalink to &quot;1. Beginnen Sie während des Trainings&quot;">​</a></h4><p><strong>Übe deine Wettkampf-Ernährung während der Trainingseinheiten:</strong></p><ul><li>Iss vor dem Training die gleiche Mahlzeit wie vor dem Wettkampf.</li><li>Bring die gleichen Snacks mit, die du auch zu einem Turnier mitbringen würdest.</li><li>Beobachte, wie dein Körper reagiert.</li><li>Passen Sie die Einstellungen an das an, was funktioniert.</li></ul><p><strong>Beispielhafter Trainingstag:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2-3 hours before: Eggs with vegetables (same as competition)</span></span>\n<span class="line"><span>During training: Water + nuts (same as competition)</span></span>\n<span class="line"><span>After training: Balanced meal with protein</span></span></code></pre></div><h4 id="_2-mach-es-zu-deiner-normalitat" tabindex="-1">2. Mach es zu deiner Normalität <a class="header-anchor" href="#_2-mach-es-zu-deiner-normalitat" aria-label="Permalink to &quot;2. Mach es zu deiner Normalität&quot;">​</a></h4><p><strong>Man sollte keine separate &quot;Wettkampfdiät&quot; und &quot;normale Diät&quot; einführen</strong> – das führt zu zwei Problemen:</p><ul><li>Ihr Körper passt sich an beides nie vollständig an</li><li>Das Essen im Wettkampf fühlt sich ungewohnt und stressig an.</li></ul><p><strong>Stattdessen:</strong></p><ul><li>Machen Sie Lebensmittel mit stabiler Energiezufuhr zu Ihrer täglichen Norm</li><li>Ihr Körper lernt, Proteine und Fette effizienter zu verwerten.</li><li>Der Wettkampftag fühlt sich normal an, nicht anders.</li><li>Keine Verdauungsüberraschungen</li></ul><h4 id="_3-testen-und-optimieren" tabindex="-1">3. Testen und Optimieren <a class="header-anchor" href="#_3-testen-und-optimieren" aria-label="Permalink to &quot;3. Testen und Optimieren&quot;">​</a></h4><p><strong>Nutzen Sie das Training zum Experimentieren:</strong></p><table tabindex="0"><thead><tr><th>Prüfen</th><th>Worauf man achten sollte</th><th>Anpassen</th></tr></thead><tbody><tr><td>Mahlzeiten vor dem Training</td><td>Energieniveau, Konzentration</td><td>Finden Sie Ihr optimales Fenster</td></tr><tr><td>Verschiedene Proteinquellen</td><td>Verdauung, Wohlbefinden</td><td>Ermitteln Sie, was am besten funktioniert</td></tr><tr><td>Snackarten</td><td>Anhaltende Energie</td><td>Finde deine Lieblingssnacks</td></tr><tr><td>Hydratationsmengen</td><td>Konzentration, Toilettenpausen</td><td>Ausgewogene Zufuhr</td></tr></tbody></table><p><strong>Führen Sie ein einfaches Protokoll:</strong></p><ul><li>Was du gegessen hast und wann</li><li>Wie Sie sich während des Trainings gefühlt haben</li><li>Energieniveau und Konzentration</li><li>Jegliche Verdauungsprobleme</li></ul><h4 id="_4-wohlbefinden-und-selbstvertrauen-aufbauen" tabindex="-1">4. Wohlbefinden und Selbstvertrauen aufbauen <a class="header-anchor" href="#_4-wohlbefinden-und-selbstvertrauen-aufbauen" aria-label="Permalink to &quot;4. Wohlbefinden und Selbstvertrauen aufbauen&quot;">​</a></h4><p><strong>Der psychologische Nutzen:</strong></p><p>Wenn du deine Ernährung im Training hunderte Male geübt hast:</p><ul><li>Du weißt genau, wie dein Körper reagieren wird.</li><li>Keine Angst vor Lebensmittelauswahl</li><li>Eine Sorge weniger am Wettkampftag</li><li>Vertrauen in Ihre Vorbereitung</li></ul><p><strong>Dies ist das gleiche Prinzip wie beim Üben Ihres Wurfs</strong> - Wiederholung schafft Sicherheit und Zuverlässigkeit.</p><h3 id="gemeinsame-anpassungsherausforderungen" tabindex="-1">Gemeinsame Anpassungsherausforderungen <a class="header-anchor" href="#gemeinsame-anpassungsherausforderungen" aria-label="Permalink to &quot;Gemeinsame Anpassungsherausforderungen&quot;">​</a></h3><details class="details custom-block"><summary>Übergang von einer kohlenhydratreichen zu einer energiestabilen Ernährung</summary><p><strong>Herausforderung:</strong> Du bist an Brot, Nudeln und zuckerhaltige Snacks gewöhnt.</p><p><strong>Eingewöhnungszeit:</strong> 2-4 Wochen</p><p><strong>Was Sie erwartet:</strong></p><ul><li>Woche 1: Möglicherweise fühlen Sie sich anders, Heißhunger auf alte Speisen</li><li>Woche 2: Energieniveau stabilisiert sich, Heißhungerattacken nehmen ab</li><li>Woche 3-4: Neue Normalität, der Körper verarbeitet Fette/Proteine effizienter.</li></ul><p><strong>So üben Sie:</strong></p><ul><li>Beginnen Sie mit einer Mahlzeit nach der anderen.</li><li>Ersetzen Sie zunächst einfache Kohlenhydrate durch komplexe Kohlenhydrate.</li><li>Erhöhen Sie schrittweise die Zufuhr von Protein und gesunden Fetten.</li><li>Üben Sie zunächst während eines Trainings mit geringem Druck.</li></ul></details><details class="details custom-block"><summary>Lebensmittel finden, die Ihnen guttun</summary><p><strong>Herausforderung:</strong> Nicht jeder verträgt die gleichen Lebensmittel gut.</p><p><strong>Was zu testen ist:</strong></p><ul><li>Verschiedene Proteinquellen (Eier vs. Fleisch vs. Nüsse)</li><li>Zeitpunkt der Mahlzeiten (2 Stunden vs. 3 Stunden vorher)</li><li>Portionsgrößen (zu viel = träge, zu wenig = hungrig)</li><li>Bestimmte Lebensmittel, die Beschwerden verursachen</li></ul><p><strong>Praktische Vorgehensweise:</strong></p><ul><li>Versuchen Sie jeweils nur eine Variable.</li><li>Für jeden Test sollten 2-3 Trainingseinheiten vorgesehen werden.</li><li>Notiere dir, was dir am besten gefällt.</li><li>Stellen Sie Ihr persönliches &quot;Wettbewerbsmenü&quot; zusammen</li></ul></details><details class="details custom-block"><summary>Umgang mit der Verpflegung bei Turnieren</summary><p><strong>Herausforderung:</strong> Bei Turnieren ist das Speisenangebot oft begrenzt.</p><p><strong>Übungslösung:</strong></p><ul><li>Bringen Sie immer Ihre eigenen Snacks mit (üben Sie das).</li><li>Erkunden Sie die Veranstaltungsorte nach Möglichkeit im Voraus.</li><li>Halten Sie Backup-Optionen bereit, von denen Sie wissen, dass sie funktionieren.</li><li>Üben Sie das Essen in verschiedenen Umgebungen</li></ul><p><strong>Mentale Vorbereitung:</strong></p><ul><li>Verlassen Sie sich nicht auf das Essen im Veranstaltungsort.</li><li>Behandeln Sie Lebensmittel als Teil Ihrer Ausrüstung.</li><li>Pack es so ein, wie du deine Boules einpackst.</li></ul></details><h3 id="der-30-tage-ernahrungsubungsplan" tabindex="-1">Der 30-Tage-Ernährungsübungsplan <a class="header-anchor" href="#der-30-tage-ernahrungsubungsplan" aria-label="Permalink to &quot;Der 30-Tage-Ernährungsübungsplan&quot;">​</a></h3><p><strong>Ziel:</strong> Eine Ernährung mit gleichmäßiger Energiezufuhr soll zu Ihrer gewohnten Routine werden.</p><p><strong>Woche 1-2: Grundlagen</strong></p><ul><li>Ersetzen Sie eine Mahlzeit pro Tag durch eine wettkampfgerechte Ernährung.</li><li>Üben Sie die Ernährung vor dem Training</li><li>Fangt an, Snacks zum Training mitzubringen.</li><li>Beobachte, wie dein Körper reagiert.</li></ul><p><strong>Woche 3-4: Expansion</strong></p><ul><li>Zwei Mahlzeiten pro Tag mit Fokus auf stabile Energiezufuhr.</li><li>Übe an Trainingstagen die Ernährung wie am Wettkampftag.</li><li>Verfeinern Sie Ihre Snackauswahl</li><li>Stelle deine Lieblingslebensmittelliste zusammen</li></ul><p><strong>Woche 5+: Meisterschaft</strong></p><ul><li>Eine Ernährung mit stabiler Energiezufuhr ist Ihre neue Normalität</li><li>Der Körper ist vollständig angepasst</li><li>Der Wettkampftag verläuft routinemäßig.</li><li>Vertrauen in Ihre Ernährung</li></ul><h3 id="ihr-wettkampf-verpflegungsset" tabindex="-1">Ihr Wettkampf-Verpflegungsset <a class="header-anchor" href="#ihr-wettkampf-verpflegungsset" aria-label="Permalink to &quot;Ihr Wettkampf-Verpflegungsset&quot;">​</a></h3><p><strong>Üben Sie, dies für jede Trainingseinheit einzupacken:</strong></p><p><strong>Vor dem Wettkampf (2-3 Stunden vorher):</strong></p><ul><li>[ ] Proteinquelle (Eier, Fleisch oder Nüsse)</li><li>[ ] Gemüse oder Salat</li><li>[ ] Gesunde Fette (Avocado, Olivenöl, Käse)</li></ul><p><strong>Während des Wettkampfs:</strong></p><ul><li>[ ] Wasserflasche (wiederbefüllbar)</li><li>[ ] Gemischte Nüsse (kleine Portionen)</li><li>[ ] Hartgekochte Eier (wenn Sie sie kühl halten können)</li><li>[ ] Käsewürfel oder Käsesticks</li><li>[ ] Trockenfleisch oder Jerky</li><li>[ ] Ersatzsnacks</li></ul><p>Je mehr Sie mit diesem Set üben, desto automatischer wird es.</p><h2 id="praktische-tipps" tabindex="-1">Praktische Tipps <a class="header-anchor" href="#praktische-tipps" aria-label="Permalink to &quot;Praktische Tipps&quot;">​</a></h2><h3 id="einfache-snacks-fur-wettbewerbe" tabindex="-1">Einfache Snacks für Wettbewerbe <a class="header-anchor" href="#einfache-snacks-fur-wettbewerbe" aria-label="Permalink to &quot;Einfache Snacks für Wettbewerbe&quot;">​</a></h3><ul><li>Gemischte Nüsse (ungesalzen)</li><li>Hartgekochte Eier</li><li>Käsewürfel</li><li>Trockenfleisch vom Rind oder Truthahn</li><li>Gemüse mit Hummus</li><li>Oliven</li></ul><h3 id="was-man-vermeiden-sollte" tabindex="-1">Was man vermeiden sollte <a class="header-anchor" href="#was-man-vermeiden-sollte" aria-label="Permalink to &quot;Was man vermeiden sollte&quot;">​</a></h3><ul><li>Snacks aus dem Verkaufsautomaten</li><li>Zuckerhaltige Sportgetränke</li><li>Gebäck und Backwaren</li><li>Süßigkeiten und Schokoriegel</li><li>Die meisten „Energieriegel“ (Zuckergehalt prüfen)</li></ul><h2 id="wichtigste-erkenntnis" tabindex="-1">Wichtigste Erkenntnis <a class="header-anchor" href="#wichtigste-erkenntnis" aria-label="Permalink to &quot;Wichtigste Erkenntnis&quot;">​</a></h2><blockquote><p>Dein Gehirn ist dein wichtigstes Werkzeug beim Pétanque. Gib ihm konstante Energie, keine Achterbahnfahrt der Gefühle. Und trainiere deine Ernährung genauso wie deinen Wurf – Wiederholung schafft Sicherheit und Zuverlässigkeit.</p></blockquote><p>Konzentriere dich auf Proteine, gesunde Fette und ausreichend Flüssigkeit. Vermeide Blutzuckerspitzen. <strong>Am wichtigsten: Mach deine Wettkampfernährung zu deiner Alltagsernährung.</strong> Dein Körper braucht Training, um Höchstleistungen zu erbringen.</p><p><strong>Denk daran:</strong> Du würdest ja auch nicht mit einer Wurftechnik zu einem Turnier gehen, die du nie geübt hast. Genauso wenig solltest du mit einer Ernährungsstrategie antreten, die du nie ausprobiert hast.</p>',52)),a(b)])}]]);export{o as __pageData,g as default};
